// === Tab: mySketch ===
//for the #wccChallenge on theme of "Connecting the dots"  ----> code by Aaron Reuland
//Made points (of minimium distance of canvas size divided by 30) with the Poisson-disc sampling algorthim.
//Then made shapes out of groups of close points with a 'gift-wrapping' algorithm.
//Then connected all nearby points with white lines and put randomGaussianed point()'s around each point.
//One of those projects I've been working on sort 'in the background' for quite awhile, with lots
//of technical challenges that I had to work thought. Feel like the level of technical difficulty 
//(for me anyways) may or may not be visible in the finished product.

let colors=['#f94144','#f3722c','#f8961e','#f9844a','#f9c74f','#90be6d','#43aa8b','#4d908e','#577590']
let finished=[]
let divy
let fg, g, left, currentVertex, nextVertex, index


function setup() {
	let w= max(windowWidth, windowHeight);
	createCanvas(w, w);
	divy= random(10, 40)
  let s = max(width, height)
	r = w/divy

	background('#277da1');


	poissonDiscSample(r)



//'Gift Wrapping' algorithm	
	noFill()
	for(let f of finished){
		let shape=[]
			for(let g of finished){

				if(dist(f.x, f.y, g.x, g.y)<=r*1.25){
          shape.push(g)
			}
		}

		fill(random(colors))
				noStroke()
			if(shape.length>2){

			shape.sort((a, b) => a.x-b.x);
			let finalShape=[]
			let left=shape[0]
			finalShape.push(left)

		for(let i=0; i<shape.length; i++){ 
			let currentVertex=shape[i]
			let nextVertex= shape[1]
			let index=2

while(index<shape.length){			

			  let checking = shape[index];
  stroke(255);
  line(currentVertex.x, currentVertex.y, checking.x, checking.y);

  const a = p5.Vector.sub(nextVertex, currentVertex);
  const b = p5.Vector.sub(checking, currentVertex);
  const crossP = a.cross(b);

  if (crossP.z < 0) {
    nextVertex = checking;
    nextIndex = index;
  }

  index = index + 1;
  if (index == shape.length) {
    if (nextVertex == left) {
      noLoop();
    } else {
      finalShape.push(nextVertex);
      currentVertex = nextVertex;
      index = 0;
      nextVertex = left;
    }
  }
}		
}			

//drawing the colored shapes, which gift wrapping algorithm generated	
			beginShape()
				for(let s of finalShape){
					vertex(s.x, s.y)
					}
				endShape(CLOSE)	

			}

	}


//drawing points, gaussian randomness from original poisson generated points
	for(let f of finished){
		push()
		for(let i=0; i<100; i++){
			stroke(255, 200)
			strokeWeight(1)
			point(f.x+ randomGaussian(0, r/4), f.y+ randomGaussian(0, r/4))
		}
		pop()	
	}



//drawing connecting lines for original poisson generated points based on proximity.	
	for(let f of finished){
			for(let g of finished){

				if(dist(f.x, f.y, g.x, g.y)<=r*1.75){

		    	let sw= map(noise(f.x/100, f.x/100, f.y/100), 0, 1, 0.2, 4)		
					strokeWeight(sw)
					stroke(255, 100)
					line(f.x, f.y, g.x, g.y)
			}
			}
	}
}


function poissonDiscSample(r) {
//Code by Daniel Shiffman, as adapted by Aaron Reuland
	let active=[]
let positions=[]
	var k= 30
	w = r / sqrt(2)
	cols = floor(width / w)
	rows = floor(height / w)
	for (let i = 0; i < cols * rows; i++) {
		positions[i] = undefined

	}

	var pos = createVector(random(width), random(height))
	let i = floor(pos.x / w)
	let j = floor(pos.y / w)
	positions[i + j * cols] = pos
	active.push(pos)


	while (active.length > 0) {
		let ranIndex = floor(random(active.length))
		var rpos = active[ranIndex]
		var found = false
		for (let n = 0; n < k; n++) {
			let sample = p5.Vector.random2D()
			let m = random(2, 2 * r)
			sample.setMag(m);
			sample.add(rpos)

			var col = floor(sample.x / w)
			var row = floor(sample.y / w)

			if (col > -1 && row > -1 && col < cols && row < rows && !positions[col + row * cols]) {

				var ok = true
				for (let i = -1; i <= 1; i++) {
					for (let j = -1; j <= 1; j++) {
						var index = (col + i) + (row + j) * cols
						let neighbor = positions[index]
						if (neighbor) {
							let d = p5.Vector.dist(sample, neighbor)
							if (d < r) {
								ok = false
							}
						}
					}
				}
				if (ok) {
					found = true
					positions[col + row * cols] = sample;
					active.push(sample)
				}
			}
		}
		if (!found) {
			active.splice(ranIndex, 1)
		}
	}

	for(let i=0; i<positions.length; i++){
		if(positions[i]){
		finished.push(positions[i])	
		}
	}	

}


function mousePressed(){
	finished=[]
	setup()
}

